/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import {
  AbsoluteFill,
  Easing,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

export type TextBuildAxis = "x" | "y";

export interface TextBuildProps {
  text: string;
  /** Build direction: "x" pushes the line sideways, "y" stacks rows. */
  axis?: TextBuildAxis;
  /** Distance a new word travels in from (px). Defaults: 88 on x, 28 on y. */
  entryOffset?: number;
  /** Space between words (px on x) or between rows (px on y, default 12). */
  gap?: number;
  /** Frames the first word takes to settle. */
  firstDuration?: number;
  /** Frames each subsequent enter/push/reflow step takes. */
  pushDuration?: number;
  /** Scale a word enters at before settling to 1. */
  entryScale?: number;
  /** Blur (px) a word enters with. Defaults: 3.5 on x, 2.4 on y. */
  entryBlur?: number;
  /** Peak blur (px) on already-placed words while they reflow. */
  reflowBlur?: number;
  /** Cubic-bezier easing for every move. */
  easing?: [number, number, number, number];
  fontSize?: number;
  /** Overrides the design system's `foreground`. */
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
}

const FONT_FAMILY = "-apple-system, BlinkMacSystemFont, sans-serif";

const MEASURE_FONT =
  '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';

/** Per-axis defaults harvested from the two legacy looks. */
const AXIS_DEFAULTS: Record<
  TextBuildAxis,
  {
    entryOffset: number;
    gap: number;
    entryBlur: number;
    /** Subtle drift the very first word settles from, on the cross axis (x)
     * or the primary axis (y). */
    firstDrift: number;
  }
> = {
  x: { entryOffset: 88, gap: 10, entryBlur: 3.5, firstDrift: 6 },
  y: { entryOffset: 28, gap: 12, entryBlur: 2.4, firstDrift: -14 },
};

/**
 * Size of each word along the build axis. On "x" this is the measured text
 * width (canvas measureText, with a `length * fontSize * 0.55` SSR fallback);
 * on "y" every row is one `fontSize` tall.
 */
function fallbackWordSizes(
  words: string[],
  axis: TextBuildAxis,
  fontSize: number,
): number[] {
  if (axis === "y") return words.map(() => fontSize);
  return words.map((w) => w.length * fontSize * 0.55);
}

function measureWordSizes(
  words: string[],
  axis: TextBuildAxis,
  fontSize: number,
  fontWeight: number,
): number[] {
  if (axis === "y") return words.map(() => fontSize);
  if (typeof document === "undefined")
    return fallbackWordSizes(words, axis, fontSize);
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) return fallbackWordSizes(words, axis, fontSize);
  ctx.font = `${fontWeight} ${fontSize}px ${MEASURE_FONT}`;
  return words.map((w) => ctx.measureText(w).width);
}

/**
 * Center coordinates for every intermediate layout. `result[k - 1][j]` is the
 * centered position of word `j` while the first `k` words are on stage, so
 * placed words can be interpolated between consecutive layouts as new words
 * land.
 */
function centeredPositions(sizes: number[], gap: number): number[][] {
  const out: number[][] = [];
  for (let k = 1; k <= sizes.length; k++) {
    let total = gap * (k - 1);
    for (let j = 0; j < k; j++) total += sizes[j];
    let cursor = -total / 2;
    const centers: number[] = [];
    for (let j = 0; j < k; j++) {
      centers.push(cursor + sizes[j] / 2);
      cursor += sizes[j] + gap;
    }
    out.push(centers);
  }
  return out;
}

function TextBuildScene({
  text,
  axis = "x",
  entryOffset,
  gap,
  firstDuration = 10,
  pushDuration = 13,
  entryScale = 0.992,
  entryBlur,
  reflowBlur = 0.8,
  easing = [0.2, 0.8, 0.2, 1],
  fontSize = 72,
  color,
  fontWeight = 600,
  speed = 1,
  className,
  theme,
  mode,
  fontFamily,
}: TextBuildProps) {
  const frame = useCurrentFrame() * speed;
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? FONT_FAMILY;
  const fill = color ?? t.foreground;

  const defaults = AXIS_DEFAULTS[axis];
  const offset = entryOffset ?? defaults.entryOffset;
  const spacing = gap ?? defaults.gap;
  const inBlur = entryBlur ?? defaults.entryBlur;

  const words = useMemo(() => text.split(" "), [text]);

  // Canvas text measurement isn't available during SSR, so the first client
  // render must also use the fallback estimate (matching the server-rendered
  // markup) before upgrading to the precise canvas measurement post-mount —
  // otherwise the two renders disagree and React logs a hydration mismatch.
  const [measured, setMeasured] = useState(false);
  useEffect(() => setMeasured(true), []);
  const sizes = useMemo(
    () =>
      measured
        ? measureWordSizes(words, axis, fontSize, fontWeight)
        : fallbackWordSizes(words, axis, fontSize),
    [measured, words, axis, fontSize, fontWeight],
  );
  const positionsAt = useMemo(
    () => centeredPositions(sizes, spacing),
    [sizes, spacing],
  );

  const n = words.length;
  const ease = Easing.bezier(easing[0], easing[1], easing[2], easing[3]);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <div
        className={className}
        style={{
          position: "relative",
          fontSize,
          fontWeight,
          color: fill,
          letterSpacing: "-0.03em",
          fontFamily: face,
          whiteSpace: "nowrap",
        }}
      >
        {words.map((word, j) => {
          const entryStart =
            j === 0 ? 0 : firstDuration + (j - 1) * pushDuration;
          const entryEnd =
            entryStart + (j === 0 ? firstDuration : pushDuration);
          const target = positionsAt[j][j];

          // Where the word enters from. Later words travel `offset` along the
          // build axis (from the right on x, from above on y). The first word
          // only drifts subtly: cross-axis on x, a short drop on y.
          const primaryFrom =
            j === 0
              ? axis === "y"
                ? target + defaults.firstDrift
                : target
              : axis === "y"
                ? target - offset
                : target + offset;
          const crossFrom = j === 0 && axis === "x" ? defaults.firstDrift : 0;

          let primary = target;
          let cross = 0;
          let opacity = 1;
          let scale = 1;
          let blur = 0;

          if (frame < entryStart) {
            opacity = 0;
            primary = primaryFrom;
            cross = crossFrom;
            scale = entryScale;
            blur = inBlur;
          } else if (frame <= entryEnd) {
            const range: [number, number] = [entryStart, entryEnd];
            const opts = {
              extrapolateLeft: "clamp" as const,
              extrapolateRight: "clamp" as const,
              easing: ease,
            };
            primary = interpolate(frame, range, [primaryFrom, target], opts);
            cross = interpolate(frame, range, [crossFrom, 0], opts);
            opacity = interpolate(frame, range, [0, 1], opts);
            scale = interpolate(frame, range, [entryScale, 1], opts);
            blur = interpolate(frame, range, [inBlur, 0], opts);
          } else {
            // Placed word: reflow between consecutive layouts as each later
            // word lands, with a soft blur pulse mid-move.
            for (let w = j + 1; w < n; w++) {
              const pushStart = firstDuration + (w - 1) * pushDuration;
              const pushEnd = pushStart + pushDuration;
              const from = positionsAt[w - 1][j];
              const to = positionsAt[w][j];
              if (frame >= pushEnd) {
                primary = to;
              } else if (frame >= pushStart) {
                primary = interpolate(frame, [pushStart, pushEnd], [from, to], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: ease,
                });
                blur = interpolate(
                  frame,
                  [pushStart, (pushStart + pushEnd) / 2, pushEnd],
                  [0, reflowBlur, 0],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
                );
                break;
              } else {
                primary = from;
                break;
              }
            }
          }

          const tx = axis === "x" ? primary : 0;
          const ty = axis === "x" ? cross : primary;

          return (
            <span
              key={`${j}-${word}`}
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                whiteSpace: "nowrap",
                // Plain 2D transforms, deliberately. `translate3d(…, 0)` and
                // `backfaceVisibility: hidden` are the same layer-promotion
                // trick wearing two hats: they buy smoothness by handing the
                // scale to the compositor, which resamples a bitmap instead of
                // re-rasterising real type. On a word that is both scaling and
                // blurring, that is the whole deliverable.
                transform: `translate(-50%, -50%) translate(${tx}px, ${ty}px) scale(${scale})`,
                filter: `blur(${blur}px)`,
                opacity,
              }}
            >
              {word}
            </span>
          );
        })}
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type TextBuildElementProps = Omit<
  ComponentProps<typeof TextBuildScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const TextBuildDefaults = {
  text: "Ship. Test. Deploy. Repeat.",
  axis: "x",
  entryOffset: 88,
  gap: 10,
  firstDuration: 10,
  pushDuration: 13,
  entryScale: 0.992,
  entryBlur: 3.5,
  reflowBlur: 0.8,
  fontSize: 72,
  color: "#101828",
  fontWeight: 600,
  speed: 1,
} satisfies Partial<TextBuildElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const TextBuildSchema = {
  text: {
    type: "text-content",
    default: "Ship. Test. Deploy. Repeat.",
    description: "Text",
  },
  fontSize: {
    type: "number",
    default: 72,
    min: 12,
    max: 160,
    step: 1,
    description: "Font size",
    hiddenFromList: false,
    keyframable: false,
  },
  color: {
    type: "color",
    default: "#101828",
    description: "Color",
    keyframable: false,
  },
  fontWeight: {
    type: "number",
    default: 600,
    min: 400,
    max: 700,
    step: 100,
    description: "Font weight",
    hiddenFromList: false,
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 1,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function TextBuildFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const TextBuildInner = forwardRef<HTMLDivElement, TextBuildElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...TextBuildDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1100}
        height={160}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1100,
            height: 101,
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: -37,
              width: 1100,
              height: 160,
            }}
          >
            <TextBuildFade>
              <TextBuildScene key={key} {...rest} />
            </TextBuildFade>
          </div>
        </div>
      </Sequence>
    );
  },
);

export const TextBuild = Interactive.withSchema({
  Component: TextBuildInner,
  componentName: "<TextBuild>",
  schema: TextBuildSchema,
  wrapInSequence: true,
});
